#!/usr/bin/env bash
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
haar=$(realpath "${2:-$here/../haar-dyadic-cycles}")
mathlib=$(realpath "${1:?Usage: bash replay-local.sh /path/to/built/mathlib4 [haar-source-dir]}")
build=$(mktemp -d)
trap 'rm -rf "$build"' EXIT
export LEAN_PATH="$build${LEAN_PATH:+:$LEAN_PATH}"
cd "$mathlib"
for m in HaarCycle HaarClass3Table HaarClass3Collect HaarOrderTwo HaarAllNoncommuting HaarBound16 HaarSharpCore HaarSharpGraph HaarHalfCollision HaarClass3Collector64 HaarAbelCore HaarAbel HaarCentral HaarClass3Cycle HaarClass3Odd HaarClass4Table HaarClass4CollectCore HaarClass4Powers HaarClass4Normal HaarVoltage HaarVoltageLift HaarClass4Graph HaarClass4Projection HaarClass4Certificates HaarClass4Gate HaarClass4Prime HaarClass4Structure HaarClass4Data HaarClass4Ports HaarClass4Generate HaarTwoKernel HaarClassThreeFinite HaarClassFourFinite HaarClass3Separation64 HaarUniversal36 HaarClass5Commute; do
  lake env lean --root="$haar" -o "$build/$m.olean" "$haar/$m.lean"
done
for m in Ribbon RibbonAbelian RibbonSharp RibbonAsymm RibbonAsymmStructure RibbonClass3Data RibbonClass3 RibbonClass3SharpGraph RibbonClass3SharpHalf RibbonClass3SharpUpper RibbonClass3SharpCert RibbonClass3Sharp RibbonClass3SharpComponent RibbonClass4Data RibbonClass4Core RibbonClass4Graph RibbonClass4Ports RibbonClass4Fallback RibbonClass4Short RibbonClass4Family RibbonClass4SharpGraph RibbonClass4SharpHalf RibbonClass4SharpCert RibbonClass4SharpUpper RibbonClass4Sharp RibbonClass4SharpComponent Ribbon5LawWords Ribbon5LawAlgebra Ribbon5BridgeChart Ribbon5ChartSound Ribbon5Walk Ribbon5Bridge64 Ribbon5GeneratorDrop Ribbon5Family Ribbon6Chart Ribbon6Algebra Ribbon6Mates Ribbon6Family Ribbon7AuxDefs Ribbon7AuxCollect Ribbon7AuxWords Ribbon7AuxLayers Ribbon7AuxFinish Ribbon7Chart Ribbon7Layers Ribbon7Algebra Ribbon7Mates Ribbon7Local Ribbon7Exceptional Ribbon7Family RibbonP3Identity RibbonP3Chart RibbonP3Collect RibbonP3Compare RibbonP3Character RibbonP3Endpoint RibbonP3Transport RibbonP3KeySound RibbonP3Glue RibbonP3Cycle RibbonP3Structure RibbonP3Local RibbonP3Odd Ribbon6Invert Ribbon6P3Chart Ribbon6P3Local Ribbon6P3Key Ribbon6P3Transport Ribbon6P3All Ribbon6Odd RibbonMetaClose RibbonMetaDirect3 RibbonMetaDrop RibbonMetaFinal RibbonMetaSharp RibbonDerivedTwoClose RibbonDerivedTwoLow RibbonDerivedTwoChart RibbonDerivedTwoP3 RibbonDerivedTwoOdd RibbonMetaHeadline Ribbon8Free Ribbon8Chart Ribbon8Algebra Ribbon8Gap Ribbon8Graph Ribbon8Family Ribbon8AltAChart Ribbon8AltAAlgebra Ribbon8AltBChart Ribbon8AltBAlgebra Ribbon8AltCChart Ribbon8AltCAlgebra Ribbon8SmallRank Ribbon8SmallCollect Ribbon8SmallData Ribbon8SmallDescent Ribbon8SmallCross Ribbon8SmallGap Ribbon8SmallFamily Ribbon8Full RibbonAffineCocycle RibbonAffineNormalize RibbonAffineScalar RibbonAffineGroup RibbonAffineWrapper RibbonAffineWords RibbonAffineCore RibbonAffinePoly RibbonAffineTorsion RibbonAffineBaseData RibbonAffineBase RibbonAffineModCore RibbonAffineModCases RibbonAffineUniversalData RibbonAffineUniversalCheck RibbonAffineUniversal RibbonAffineFinal; do
  lake env lean --root="$here" -o "$build/$m.olean" "$here/$m.lean"
done
